{"plan": "O cenário inicializa a conta Ledger com total_supply=100 e user_balance=0 via a instrução initialize (baseline). Em seguida, o ataque chama burn com amount=1, o que deveria causar underflow em user_balance (0 - 1). Como o programa usa checked_sub e retorna ArithmeticUnderflow, o ataque deve ser rejeitado. O efeito medido seria a alteração indevida de user_balance ou total_supply, mas como o ataque falha, nenhum efeito é registrado.", "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let baseline_result = env.baseline("initialize ledger", &init_ix, &init_accounts);

let ledger_data = after(&baseline_result, &ledger_key).data().to_vec();
let ledger_account = account(&env.program_id, &ledger_data, None);

let burn_ix = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let burn_accounts = vec![
    (ledger_key, ledger_account),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("burn underflow", &burn_ix, &burn_accounts);

if attack_result.program_result == ProgramResult::Success {
    let user_balance = read_u64(after(&attack_result, &ledger_key).data(), 40);
    let total_supply = read_u64(after(&attack_result, &ledger_key).data(), 72);
    env.effect("user_balance underflowed", user_balance > 100);
    env.effect("total_supply underflowed", total_supply > 100);
}"}

